# Let me search for all data files for January debt figures more carefully
# Looking for any numbers between 300000-450000 range that appear with year patterns
python3 << 'EOF'
import re

with open('/app/resources/treasury_bulletin_1969_10.txt') as f:
    content = f.read()

# Look for rows with the FD-1 debt table structure: | YEAR-Month | large_number | ...
# The pattern is typically: | YEAR-Month | Total | Public debt | Agency | ...

# Let's find all lines with debt totals in the range 300000-450000
lines = content.split('\n')
for i, line in enumerate(lines):
    if '1969-January' in line:
        print(f"Line {i}: {line[:250]}")

# Also find lines with "1970-January" if any
for i, line in enumerate(lines):
    if '1970-January' in line:
        print(f"Line {i}: {line[:250]}")

# And for all other years
for year in range(1971, 1981):
    for i, line in enumerate(lines):
        if f'{year}-January' in line:
            print(f"Line {i}: {line[:250]}")
EOF
